if (typeof msg.payload !== 'object' ||
    typeof msg.payload.hmi !== 'object' ||
    typeof msg.payload.project !== 'string'
) {
    return;
}

msg.filename = '/data/projects/' + msg.payload.project + '/package.json'

msg.payload.app = {
    'title': 'DKNR',
    'version' : '0.0',
    'git': '',
    'mdi': ''
}

global.set('describe', msg.payload, 'memoryOnly');

return msg;

// DKNR MQTT topic
const enabled = global.get('mqtt.enabled', 'default') || false;
const topic = global.get('mqtt.topic', 'default') || '';
if (!enabled || topic === '') {

    return;
}

const ha_topic = global.get('mqtt.homeassistant', 'default') || '';
const describe = global.get('describe', 'memoryOnly') || {};
const controls = global.get('controls', 'memoryOnly') || {};
const source = 'rfxcom';

// Source definition
let srcMsg = {
    'topic': [topic, 'discovery', source].join('/'),
    'payload': describe.app,
    'qos': 0,
    'retain': true
};

node.send([srcMsg]);

for (const k in controls) {
    const c = controls[k];

    // topic as uid must be source _ id _ entry
    node.send({
        'topic': [topic, 'discovery', source, c.device, c.entity].join('/'),
        'payload': {
            'name': c.name,
            'group': c.group,
            'type': c.type,
            'unit': c.unit,
            'value': c.value,
            'options': c.options || {}
        },
        'qos': 0,
        'retain': true
    });

    // ha
    if (ha_topic === '') {

        continue;
    }

    let payload = {
        'unique_id': ['dknr', source, c.device, c.entity].join('_'),
        'name': c.name,
        'state_topic': [topic, 'get', source, c.device, c.entity].join('/'),
        'device': {
            'identifiers': [
                c.device
            ],
            'manufacturer': 'RFXCom',
            'model': c.model || 'rfxcom ' + c.device,
            'name': 'RFXCom ' + c.device
        }
    };

    if (c.ha_category !== '' && c.ha_category !== undefined) {
        payload.entity_category = c.ha_category;
    }

    if (c.ha_type === 'sensor') {
        if (c.unit !== '') {
            payload.unit_of_measurement = c.unit;
        }
        if (c.ha_state !== '') {
            payload.state_class = c.ha_state;
        }
        if (c.ha_device !== '') {
            payload.device_class = c.ha_device;
        }
        if (c.ha_device === 'enum') {
            payload.options = [...new Set(Object.values(c.options || {}))];
        }
    }
    else if (c.ha_type === 'binary_sensor') {
        payload.payload_on = 'ON';
        payload.payload_off = 'OFF';
        if (c.ha_device !== '') {
            payload.device_class = c.ha_device;
        }
    }
    else if (c.ha_type === 'switch') {
        payload.command_topic = [topic, 'set', source, c.device, c.entity].join('/');
        payload.payload_on = 'ON';
        payload.payload_off = 'OFF';
        payload.state_on = 'ON';
        payload.state_off = 'OFF';
    }
    else {

        continue;
    }

    node.send({
        'topic': [ha_topic, c.ha_type, source, c.device + '_' + c.entity, 'config'].join('/'),
        'payload': payload,
        'qos': 0,
        'retain': true
    });
}

return;

const mqtt = global.get('mqtt', 'default') || { };
if (!mqtt.enabled || typeof mqtt.source !== 'string' || mqtt.source === '') {
    node.status({ 'fill': 'red', 'text': 'settings nok' });

    return;
}

msg.topic = [mqtt.source, 'devices', '#'].join('/');
msg.payload = '';
msg.broker = {};
msg.broker.broker = mqtt.host;
msg.broker.port = mqtt.port;
msg.broker.username = mqtt.username;
msg.broker.password = mqtt.password;

msg.broker.force = true;
msg.action = 'connect';

node.send([RED.util.cloneMessage(msg)]);

delete msg.broker;

await new Promise(resolve => setTimeout(resolve, 1000));

// rfxcom2mqtt devices messages
msg.topic = [mqtt.source, 'devices', '#'].join('/');
msg.payload = '';
msg.action = 'subscribe';
msg.qos = 1;

node.send([RED.util.cloneMessage(msg)]);

// DKNR commands: topic / set / rfxcom / device / entity
if (typeof mqtt.topic === 'string' && mqtt.topic !== '') {
    msg.topic = [mqtt.topic, 'set', 'rfxcom', '#'].join('/');

    node.send([RED.util.cloneMessage(msg)]);
}

node.status({fill:"green",shape:"ring",text:"settings ok"});

return;

// Translate rfxcom2mqtt message (node-rfxcom event) to DKNR entities
// output 1: DKNR MQTT values / output 2: new entity found (discovery)

const p = msg.payload;
if (typeof p !== 'object' || p === null || Array.isArray(p) || typeof p.type !== 'string') {

    return;
}

// Remove this type
const disabled = global.get('disabled', 'default') || [];
for (let i = 0; i < disabled.length; i++) {
    if (Object.hasOwn(p, disabled[i][0]) && String(p[disabled[i][0]]) === String(disabled[i][1])) {

        return;
    }
}

const describe = global.get('describe', 'memoryOnly') || {};
const defs = describe.rfxcom || {};
const topic = global.get('mqtt.topic', 'default') || '';
const source = 'rfxcom';

// Device identifier, without 0x
const rawId = p.type === 'lighting4' ? p.data : p.id;
if (typeof rawId !== 'string' || rawId === '') {

    return;
}
const device = rawId.replace(/^0x/i, '');
const controls = global.get('controls', 'memoryOnly') || {};

// Device model, keep the one already known when this event does not give it
let model = Array.isArray(p.deviceName) ? p.deviceName.filter(n => n !== '').join(', ') : (p.deviceName || '');
if (model === '') {
    const known = Object.values(controls).find(c => c.device === device && c.model);
    model = known ? known.model : (p.subTypeValue || p.type);
}
const commands = global.get('commands', 'default') || {};
let added = false;
let values = [];

// Register an entity value
function add(key, value, suffix, display) {
    const def = defs[key];
    if (typeof def !== 'object' || value === undefined || value === null || (typeof value === 'number' && isNaN(value))) {

        return;
    }

    const entity = def.entity + (suffix || '');
    const uid = device + '_' + entity;

    if (typeof controls[uid] !== 'object') {
        added = true;
    }

    controls[uid] = {
        'device': device,
        'entity': entity,
        'name': def.name + (suffix ? ' ' + suffix : ''),
        'group': def.ha_type === 'switch' ? 'command' : 'sensor',
        'type': def.type,
        'unit': def.unit,
        'value': value,
        'display': display !== undefined ? display : String(value) + (def.unit ? ' ' + def.unit : ''),
        'options': def.options || {},
        'ha_type': def.ha_type,
        'ha_state': def.ha_state,
        'ha_device': def.ha_device,
        'ha_category': def.category || '',
        'model': model,
        'rfxtype': p.type
    };

    values.push([uid, entity, value]);
}

function round(v, d) {
    const f = Math.pow(10, d);

    return Math.round(v * f) / f;
}

// ---- commands (switches, remotes, doorbells...)
const switchTypes = ['lighting1', 'lighting2', 'lighting5', 'lighting6'];
const command = typeof p.command === 'string' ? p.command.toLowerCase() : '';
const isOn = ['on', 'group on', 'all on', 'set level', 'set group level'].includes(command);
const isOff = ['off', 'group off', 'all off'].includes(command);

if (switchTypes.includes(p.type) && (isOn || isOff)) {
    const state = isOn ? 'ON' : 'OFF';
    if (p.group === true || command.startsWith('group') || command.startsWith('all')) {
        add('group', state, '', isOn ? 'Allumé' : 'Eteint');
    } else {
        const unit = p.unitCode !== undefined ? p.unitCode : 1;
        add('switch', state, String(unit), isOn ? 'Allumé' : 'Eteint');

        // keep what is needed to send command back through rfxcom2mqtt
        commands[device + '_' + defs['switch'].entity + unit] = {
            'type': p.type,
            'subtype': p.subtype,
            'id': p.id,
            'unit': unit
        };
        global.set('commands', commands, 'default');

        if (p.type === 'lighting2' && command.includes('level') && typeof p.level === 'number') {
            add('level', Math.round(p.level / 15 * 100), String(unit));
        }
    }
} else if (typeof p.command === 'string' && p.command !== '' && p.command !== 'Unknown') {
    add('command', p.command, p.unitCode !== undefined ? String(p.unitCode) : '');
    add('lastSeen', new Date().toISOString(), '', new Date().toLocaleString('fr-FR', { 'timeZone': env.get('TZ') || 'Europe/Paris' }));
}

// ---- sensors
for (const key in p) {
    let v = p[key];

    switch (key) {
        case 'temperature':
        case 'current':
            if (Array.isArray(v)) {
                v.forEach((x, i) => add(key, round(x, 2), String(i + 1)));
            } else {
                add(key, round(v, 2));
            }
            break;
        case 'humidityStatus':
        case 'forecast':
        case 'deviceStatus':
            add(key, defs[key].options[String(v)], '', defs[key].options[String(v)]);
            if (key === 'deviceStatus') {
                if (v === 4 || v === 5) {
                    add('motion', v === 4 ? 'ON' : 'OFF', '', v === 4 ? 'Oui' : 'Non');
                } else if (v >= 0 && v <= 3) {
                    add('alarm', v >= 2 ? 'ON' : 'OFF', '', v >= 2 ? 'Oui' : 'Non');
                }
            }
            break;
        case 'tampered':
            add(key, v ? 'ON' : 'OFF', '', v ? 'Oui' : 'Non');
            break;
        case 'batteryLevel':
            // 0 to 9, 9 is full
            add(key, Math.min(100, (Number(v) + 1) * 10));
            break;
        case 'rssi':
            // 0 to 15
            add(key, Math.round(Number(v) / 15 * 100));
            break;
        case 'energy':
            add(key, round(v, 1));
            break;
        case 'level':
            if (p.type === 'waterlevel') {
                add('waterLevel', v);
            }
            break;
        case 'compteur':
            if (Array.isArray(v)) {
                v.forEach((c, i) => {
                    if (typeof c === 'object' && c !== null) {
                        add(c['unité'] === 'Wh' ? 'compteurWh' : 'compteurImpulsions', c.valeur, String(i + 1));
                    }
                });
            }
            break;
        case 'humidity':
        case 'barometer':
        case 'rainfall':
        case 'rainfallRate':
        case 'direction':
        case 'averageSpeed':
        case 'gustSpeed':
        case 'chillfactor':
        case 'uv':
        case 'co2':
        case 'weight':
        case 'power':
        case 'voltage':
        case 'powerFactor':
        case 'frequency':
        case 'counter':
        case 'batteryVoltage':
        case 'percent':
        case 'angle':
        case 'setpoint':
        case 'indexTariffaireEnCours':
        case 'tensionMoyenne':
            add(key, typeof v === 'number' ? round(v, 2) : v);
            break;
        case 'puissanceApparente':
            if (p.puissanceApparenteValide !== false) {
                add(key, v);
            }
            break;
        case 'mode':
        case 'status':
        case 'typeContrat':
        case 'avertissementCouleurAujourdHui':
        case 'avertissementCouleurDemain':
            if (typeof v === 'string' && v !== '') {
                add(key, v);
            }
            break;
    }
}

global.set('controls', controls, 'memoryOnly');

// ---- DKNR values, only on change
for (const [uid, entity, value] of values) {
    if (flow.get('last["' + uid + '"]', 'memoryOnly') === value) {

        continue;
    }
    flow.set('last["' + uid + '"]', value, 'memoryOnly');

    if (topic !== '') {
        node.send([{
            'topic': [topic, 'get', source, device, entity].join('/'),
            'payload': value,
            'qos': 0,
            'retain': false
        }, null]);
    }
}

node.status({ 'fill': 'green', 'shape': 'dot', 'text': device + ' (' + p.type + ') : ' + values.length });

if (added) {
    node.send([null, { 'payload': 'discovery' }]);
}

return;

// DKNR command: topic / set / rfxcom / device / entity = ON, OFF
// sent to rfxcom2mqtt: source / cmd / type / subtype / id / unit = On, Off

const mqtt = global.get('mqtt', 'default') || {};
const commands = global.get('commands', 'default') || {};
const source = 'rfxcom';

const path = msg.topic.split('/');
if (path.length < 5) {

    return;
}

const entity = path.pop();
const device = path.pop();
const cmd = commands[device + '_' + entity];
const value = (msg.payload === undefined || msg.payload === null ? '' : msg.payload).toString().trim().toUpperCase();

if (typeof cmd !== 'object') {
    node.status({ 'fill': 'red', 'shape': 'ring', 'text': device + ' - ' + entity + ' : inconnu' });

    return;
}

let state = '';
if (['ON', '1', 'TRUE'].includes(value)) {
    state = 'ON';
} else if (['OFF', '0', 'FALSE'].includes(value)) {
    state = 'OFF';
} else {
    node.status({ 'fill': 'red', 'shape': 'ring', 'text': device + ' - ' + entity + ' : ' + value + ' ?' });

    return;
}

if (typeof mqtt.source !== 'string' || mqtt.source === '') {

    return;
}

node.status({ 'fill': 'green', 'shape': 'dot', 'text': device + ' - ' + entity + ' - ' + state });

// Optimistic state, the device does not answer
flow.set('last["' + device + '_' + entity + '"]', state, 'memoryOnly');
const controls = global.get('controls', 'memoryOnly') || {};
if (typeof controls[device + '_' + entity] === 'object') {
    controls[device + '_' + entity].value = state;
    controls[device + '_' + entity].display = state === 'ON' ? 'Allumé' : 'Eteint';
    global.set('controls', controls, 'memoryOnly');
}

node.send({
    'topic': [mqtt.source, 'cmd', cmd.type, cmd.subtype, cmd.id, cmd.unit].join('/'),
    'payload': state === 'ON' ? 'On' : 'Off',
    'qos': 1,
    'retain': false
});

node.send({
    'topic': [mqtt.topic, 'get', source, device, entity].join('/'),
    'payload': state,
    'qos': 0,
    'retain': false
});

return;

const disabled = global.get('disabled', 'default') || { };

msg.payload = [];

for (let i = 0; i < disabled.length; i++) {
    msg.payload.push({
        'index': i,
        'key': disabled[i][0],
        'value': disabled[i][1],
        'delete': 'Supprimer'
    });
}

return msg;

if (msg.payload.key !== '' && msg.payload.value !== '') {
    let disabled = global.get('disabled', 'default');
    disabled.push([msg.payload.key, msg.payload.value]);
    msg.payload = '';

    await new Promise(resolve => setTimeout(resolve, 10));

    return msg;
}

return;

if (msg.action === 'button_click' && msg.column === 'delete') {
    let disabled = global.get('disabled', 'default');
    disabled.splice(msg.payload.index, 1);
    msg.payload = '';

    return msg;
}

return;

const controls = global.get('controls', 'memoryOnly') || { };

msg.payload = [];

for (const k of Object.keys(controls).sort()) {
    msg.payload.push({
        'device': controls[k].device,
        'model': controls[k].model || '',
        'name': controls[k].name,
        'value': controls[k].display !== undefined ? controls[k].display : String(controls[k].value)
    });
}

return msg;
